(() => {
  'use strict';

  const hospitals = [
    { id: 1, name: 'Lagos University Teaching Hospital', city: 'Lagos', state: 'Lagos', category: 'Teaching Hospital', rating: 4.7, reviews: 328, emergency: true, open24: true, verified: true, phone: '+234 801 234 5678', services: ['Cardiology', 'Emergency Care', 'Paediatrics'], lat: 34, lng: 26 },
    { id: 2, name: 'National Hospital Abuja', city: 'Abuja', state: 'FCT', category: 'Teaching Hospital', rating: 4.8, reviews: 412, emergency: true, open24: true, verified: true, phone: '+234 809 876 5432', services: ['Oncology', 'Emergency Care', 'Surgery'], lat: 62, lng: 52 },
    { id: 3, name: 'University of Calabar Teaching Hospital', city: 'Calabar', state: 'Cross River', category: 'Teaching Hospital', rating: 4.4, reviews: 186, emergency: true, open24: true, verified: true, phone: '+234 805 112 2334', services: ['Cardiology', 'Maternity', 'Laboratory'], lat: 76, lng: 75 },
    { id: 4, name: 'Rivers State University Teaching Hospital', city: 'Port Harcourt', state: 'Rivers', category: 'Teaching Hospital', rating: 4.5, reviews: 241, emergency: true, open24: true, verified: true, phone: '+234 803 445 6677', services: ['Emergency Care', 'Dentistry', 'Radiology'], lat: 42, lng: 70 },
    { id: 5, name: 'Eko Hospital', city: 'Lagos', state: 'Lagos', category: 'Private Hospital', rating: 4.3, reviews: 154, emergency: false, open24: false, verified: true, phone: '+234 802 765 4321', services: ['Cardiology', 'Dentistry', 'Physiotherapy'], lat: 25, lng: 35 },
    { id: 6, name: 'Life First Medical Centre', city: 'Enugu', state: 'Enugu', category: 'Medical Centre', rating: 4.1, reviews: 89, emergency: false, open24: true, verified: false, phone: '+234 807 333 2211', services: ['Maternity', 'Laboratory', 'Paediatrics'], lat: 66, lng: 82 }
  ];
  const savedHospitals = JSON.parse(localStorage.getItem('medilocate-hospitals') || 'null');
  if (Array.isArray(savedHospitals)) hospitals.splice(0, hospitals.length, ...savedHospitals);
  const state = { view: 'landing', previousView: 'landing', results: [...hospitals], radius: 25, mapZoom: 1, mapType: 'road', userLocation: null };
  const demoUsers = [
    { email: 'patient@medilocate.ng', password: 'Patient123!', name: 'Adaeze Patient', role: 'patient' },
    { email: 'provider@medilocate.ng', password: 'Provider123!', name: 'Dr. Daniel Okafor', role: 'provider' },
    { email: 'admin@medilocate.ng', password: 'Admin123!', name: 'MediLocate Admin', role: 'admin' }
  ];
  const defaultReviews = {
    1: [{ name: 'Chinwe A.', rating: 5, text: 'Excellent emergency response and very helpful staff.', date: '2 weeks ago' }, { name: 'Musa K.', rating: 4, text: 'The facility was easy to find and the care team was professional.', date: '1 month ago' }],
    2: [{ name: 'Ifeoma N.', rating: 5, text: 'Clean facility with a clear admissions process.', date: '3 weeks ago' }],
    3: [{ name: 'Samuel E.', rating: 4, text: 'Good specialists and a reliable laboratory service.', date: '1 month ago' }]
  };
  const $ = (id) => document.getElementById(id);
  const esc = (value) => String(value).replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));

  function toast(message, type = 'ok') {
    const root = $('toasts');
    if (!root) return;
    const item = document.createElement('div');
    item.className = `toast ${type === 'error' ? 'err' : type === 'warn' ? 'warn' : ''}`;
    item.innerHTML = `<span class="t-ic">${type === 'error' ? '⚠️' : type === 'warn' ? 'ℹ️' : '✓'}</span><span>${esc(message)}</span>`;
    root.appendChild(item);
    window.setTimeout(() => item.remove(), 3600);
  }

  function showView(id) {
    document.querySelectorAll('.view').forEach((view) => view.classList.add('hidden'));
    $(id)?.classList.remove('hidden');
    $('app')?.classList.add('hidden');
    state.previousView = state.view;
    state.view = id.replace('view-', '');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
  window.goLanding = () => showView('view-landing');
  window.openLocator = () => { showView('view-locator'); populateFilters(); applyFilters(); };
  window.openServices = () => { showView('view-services'); renderServices(); };
  window.openContact = () => showView('view-contact');
  window.goBackFromPublic = () => showView(`view-${state.previousView === 'landing' ? 'landing' : state.previousView}`);
  window.openEmergency = () => { showView('view-emergency'); renderEmergency(); };

  function hospitalCard(hospital, compact = false) {
    const badges = `${hospital.verified ? '<span class="badge badge-verified">✓ Verified</span>' : ''}${hospital.emergency ? '<span class="badge badge-emergency">🚨 Emergency</span>' : ''}`;
    return `<article class="h-card"><div class="h-cover ${hospital.id % 2 ? '' : 'alt'}"><span class="initials">${esc(hospital.name.split(' ').map((word) => word[0]).slice(0, 2).join(''))}</span>${badges}</div><div class="h-body"><div class="h-name">${esc(hospital.name)}</div><div class="h-meta">📍 ${esc(hospital.city)}, ${esc(hospital.state)} · ${hospital.category}</div><div class="h-rating"><span class="stars">★★★★★</span> ${hospital.rating} <span class="h-meta">(${hospital.reviews} reviews)</span></div><div class="h-services">${hospital.services.slice(0, compact ? 2 : 3).map((service) => `<span class="chip">${esc(service)}</span>`).join('')}</div><div class="h-foot"><button class="btn btn-outline" onclick="showHospital(${hospital.id})">Details</button><a class="btn btn-primary" href="tel:${hospital.phone.replace(/\s/g, '')}">Call</a></div></div></article>`;
  }
  window.showHospital = (id) => { const hospital = hospitals.find((item) => item.id === id); if (!hospital) return; const reviews = getHospitalReviews(id); const session = JSON.parse(sessionStorage.getItem('medilocate-session') || 'null'); openModal(`<div class="modal-head"><h3>${esc(hospital.name)}</h3><button class="close-x" onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-body"><p class="h-meta">📍 ${esc(hospital.city)}, ${esc(hospital.state)}</p><p style="margin-top:12px"><b>${hospital.rating} ★</b> from ${hospital.reviews} reviews</p><p style="margin-top:12px">${hospital.emergency ? 'Emergency care available.' : 'Routine care facility.'} ${hospital.open24 ? 'Open 24 hours.' : 'Opening hours vary.'}</p><p style="margin-top:12px"><b>Services:</b> ${hospital.services.map(esc).join(', ')}</p><section class="review-section"><div class="review-section-head"><h4>Patient reviews</h4><span class="badge badge-info">${reviews.length} shown</span></div><div class="review-list">${reviews.length ? reviews.map((review) => `<article class="review-card"><div class="review-card-head"><div><b>${esc(review.name)}</b><span class="review-date">${esc(review.date)}</span></div><span class="stars">${'★'.repeat(review.rating)}${'☆'.repeat(5 - review.rating)}</span></div><p>${esc(review.text)}</p></article>`).join('') : '<div class="review-empty">No patient reviews yet. Be the first to share your experience.</div>'}</div>${session?.role === 'patient' ? '<button class="btn btn-outline btn-block" style="margin-top:14px" onclick="openReviewForm(' + id + ')">✎ Write a review</button>' : '<p class="review-note">Sign in as a patient to share a review.</p>'}</section></div><div class="modal-foot"><a class="btn btn-primary" href="tel:${hospital.phone.replace(/\s/g, '')}">📞 Call ${esc(hospital.phone)}</a><button class="btn btn-outline" onclick="closeModal()">Close</button></div>`, 'lg'); };
  function getHospitalReviews(id) { const stored = JSON.parse(localStorage.getItem('medilocate-reviews') || '{}'); return [...(defaultReviews[id] || []), ...(stored[id] || [])]; }
  window.openReviewForm = (id) => { const hospital = hospitals.find((item) => item.id === id); if (!hospital) return; openModal(`<div class="modal-head"><h3>Review ${esc(hospital.name)}</h3><button class="close-x" onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-body"><form onsubmit="saveHospitalReview(event,${id})"><div class="field"><label for="review-rating">Your rating</label><select id="review-rating" required><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Needs improvement</option><option value="1">1 - Poor</option></select></div><div class="field"><label for="review-text">Your experience</label><textarea id="review-text" rows="4" required minlength="12" placeholder="Tell other patients what they should know"></textarea></div><button class="btn btn-primary btn-block" type="submit">Publish review</button></form></div>`); };
  window.saveHospitalReview = (event, id) => { event.preventDefault(); const session = JSON.parse(sessionStorage.getItem('medilocate-session') || 'null'); if (!session || session.role !== 'patient') { toast('Only signed-in patients can publish reviews.', 'warn'); return; } const stored = JSON.parse(localStorage.getItem('medilocate-reviews') || '{}'); stored[id] = stored[id] || []; const rating = Number($('review-rating').value); stored[id].push({ name: session.name, rating, text: $('review-text').value.trim(), date: 'Just now' }); localStorage.setItem('medilocate-reviews', JSON.stringify(stored)); const hospital = hospitals.find((item) => item.id === id); const allReviews = getHospitalReviews(id); hospital.reviews += 1; hospital.rating = Number((allReviews.reduce((sum, review) => sum + review.rating, 0) / allReviews.length).toFixed(1)); if (localStorage.getItem('medilocate-hospitals')) localStorage.setItem('medilocate-hospitals', JSON.stringify(hospitals)); closeModal(); toast('Your patient review was published.'); showHospital(id); };
  function openModal(content, size = '') { $('modal-root').innerHTML = `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal ${size}">${content}</div></div>`; }
  window.closeModal = () => { $('modal-root').innerHTML = ''; };
  window.openAuth = (mode = 'login', requestedRole = 'patient') => {
    const isLogin = mode === 'login';
    const hint = isLogin ? '<div class="auth-hint"><b>Demo access</b><br>Patient: patient@medilocate.ng / Patient123!<br>Provider: provider@medilocate.ng / Provider123!<br>Admin: admin@medilocate.ng / Admin123!</div>' : '<div class="auth-hint">Registration is stored locally in this browser for this demo.</div>';
    openModal(`<div class="auth-layout"><div class="auth-visual"><div><span class="pill">Secure local session</span><h3>${isLogin ? 'Care starts with a clear next step.' : 'Put your facility on the map.'}</h3><p>Sign in to save searches, follow facilities and manage your MediLocate workspace.</p></div></div><div class="auth-form"><div class="modal-head"><h3>${isLogin ? 'Welcome back' : 'Create your account'}</h3><button class="close-x" onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-body">${hint}<div class="auth-error hidden" id="auth-error"></div><form id="auth-form" data-mode="${mode}" onsubmit="submitAuth(event)"><div class="field"><label for="auth-email">Email address</label><input id="auth-email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="field"><label for="auth-password">Password</label><input id="auth-password" type="password" required minlength="6" autocomplete="${isLogin ? 'current-password' : 'new-password'}" placeholder="At least 6 characters"></div>${isLogin ? '' : `<div class="field"><label for="auth-name">Full name</label><input id="auth-name" required placeholder="Your name"></div><div class="field"><label for="auth-role">Account type</label><select id="auth-role"><option value="${requestedRole === 'provider' ? 'provider' : 'patient'}">${requestedRole === 'provider' ? 'Hospital provider' : 'Patient'}</option><option value="${requestedRole === 'provider' ? 'patient' : 'provider'}">${requestedRole === 'provider' ? 'Patient' : 'Hospital provider'}</option></select></div>`}<button class="btn btn-primary btn-block" type="submit">${isLogin ? 'Sign in securely' : 'Create local account'}</button></form></div></div></div>`, 'lg');
  };
  window.submitAuth = (event) => {
    event.preventDefault();
    const form = event.currentTarget;
    const email = $('auth-email').value.trim().toLowerCase();
    const password = $('auth-password').value;
    const error = $('auth-error');
    const localUsers = JSON.parse(localStorage.getItem('medilocate-users') || '[]');
    const users = [...demoUsers, ...localUsers];
    if (form.dataset.mode === 'login') {
      const user = users.find((candidate) => candidate.email === email && candidate.password === password);
      if (!user) { error.textContent = 'Email or password is incorrect. Use one of the demo accounts shown above.'; error.classList.remove('hidden'); return; }
      startSession(user);
      return;
    }
    if (users.some((candidate) => candidate.email === email)) { error.textContent = 'An account with this email already exists. Try signing in instead.'; error.classList.remove('hidden'); return; }
    const user = { email, password, name: $('auth-name').value.trim(), role: $('auth-role').value };
    localStorage.setItem('medilocate-users', JSON.stringify([...localUsers, user]));
    startSession(user);
  };

  function startSession(user) {
    sessionStorage.setItem('medilocate-session', JSON.stringify(user));
    closeModal();
    document.querySelectorAll('.view').forEach((view) => view.classList.add('hidden'));
    $('app').classList.remove('hidden');
    $('tb-name').textContent = user.name;
    $('tb-role').textContent = user.role;
    $('tb-avatar').textContent = user.name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase();
    $('side-nav').innerHTML = user.role === 'admin' ? '<div class="s-sect">Administration</div><button class="s-link active" onclick="adminSetSection(\'overview\')"><span class="ic">▦</span>Overview</button><button class="s-link" onclick="adminSetSection(\'hospitals\')"><span class="ic">🏥</span>Hospitals</button><button class="s-link" onclick="adminSetSection(\'users\')"><span class="ic">♙</span>Users</button><button class="s-link" onclick="adminSetSection(\'moderation\')"><span class="ic">✓</span>Moderation</button>' : '';
      $('main-content').innerHTML = user.role === 'admin' ? adminMarkup(user) : dashboardMarkup(user);
      if (user.role === 'patient') renderPatientAppointments();
    toast(`Signed in as ${user.name}.`);
  }
  function dashboardMarkup(user) {
      function renderPatientAppointments() {
        const appointments = JSON.parse(localStorage.getItem('medilocate-appointments') || '[]');
        const dashboard = $('main-content');
        if (!dashboard || $('patient-appointments')) return;
        const hospitalsForBooking = hospitals.slice(0, 6);
        dashboard.querySelector('.dashboard-lower')?.insertAdjacentHTML('beforebegin', `<section class="patient-appointments module-card" id="patient-appointments"><div class="module-heading"><div><span class="kicker">Care planning</span><h3>My appointments</h3><p class="module-subtitle">Book and manage your next hospital visit from this offline workspace.</p></div><button class="btn btn-primary" onclick="openAppointmentBooking()">+ Book appointment</button></div><div id="appointment-list">${appointmentListMarkup(appointments)}</div></section>`);
      }
      function appointmentListMarkup(appointments) {
        if (!appointments.length) return '<div class="appointment-empty"><span>📅</span><div><b>No appointments booked yet</b><p>Choose a hospital and time to plan your next visit.</p></div><button class="text-button" onclick="openAppointmentBooking()">Book your first appointment →</button></div>';
        return `<div class="appointment-list">${appointments.map((appointment) => `<article class="appointment-item"><div class="appointment-date"><strong>${esc(new Date(`${appointment.date}T00:00:00`).toLocaleDateString('en-US', { day: '2-digit' }))}</strong><span>${esc(new Date(`${appointment.date}T00:00:00`).toLocaleDateString('en-US', { month: 'short' }))}</span></div><div class="appointment-details"><b>${esc(appointment.hospital)}</b><p>${esc(appointment.service)} · ${esc(appointment.time)}</p><small>📍 ${esc(appointment.location)} · ${esc(appointment.reason)}</small></div><span class="badge badge-info">${esc(appointment.status)}</span><button class="btn btn-outline btn-sm" onclick="cancelAppointment('${appointment.id}')">Cancel</button></article>`).join('')}</div>`;
      }
      window.openAppointmentBooking = () => {
        const today = new Date().toISOString().slice(0, 10);
        openModal(`<div class="modal-head"><h3>Book an appointment</h3><button class="close-x" onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-body"><p class="panel-note">Select a facility, service, and preferred time. This offline booking is saved in your browser.</p><form id="appointment-form" onsubmit="saveAppointment(event)"><div class="field"><label for="appointment-hospital">Hospital</label><select id="appointment-hospital" required>${hospitals.map((hospital) => `<option value="${hospital.id}">${esc(hospital.name)} · ${esc(hospital.city)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="appointment-service">Service</label><select id="appointment-service" required>${[...new Set(hospitals.flatMap((hospital) => hospital.services))].sort().map((service) => `<option>${esc(service)}</option>`).join('')}</select></div><div class="field"><label for="appointment-date">Date</label><input id="appointment-date" type="date" min="${today}" required></div><div class="field"><label for="appointment-time">Time</label><select id="appointment-time" required><option>08:00 AM</option><option>09:30 AM</option><option>11:00 AM</option><option>01:30 PM</option><option>03:00 PM</option></select></div><div class="field"><label for="appointment-reason">Visit reason</label><input id="appointment-reason" required placeholder="e.g. Follow-up consultation"></div></div><button class="btn btn-primary btn-block" type="submit">Confirm appointment</button></form></div>`,'lg');
      };
      window.saveAppointment = (event) => {
        event.preventDefault();
        const hospital = hospitals.find((item) => item.id === Number($('appointment-hospital').value));
        const appointments = JSON.parse(localStorage.getItem('medilocate-appointments') || '[]');
        appointments.push({ id: `apt-${Date.now()}`, hospital: hospital.name, location: `${hospital.city}, ${hospital.state}`, service: $('appointment-service').value, date: $('appointment-date').value, time: $('appointment-time').value, reason: $('appointment-reason').value.trim(), status: 'Confirmed' });
        appointments.sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));
        localStorage.setItem('medilocate-appointments', JSON.stringify(appointments));
        closeModal();
        renderPatientAppointments();
        $('appointment-list').innerHTML = appointmentListMarkup(appointments);
        toast('Appointment booked successfully.');
      };
      window.cancelAppointment = (id) => {
        const appointments = JSON.parse(localStorage.getItem('medilocate-appointments') || '[]').filter((appointment) => appointment.id !== id);
        localStorage.setItem('medilocate-appointments', JSON.stringify(appointments));
        $('appointment-list').innerHTML = appointmentListMarkup(appointments);
        toast('Appointment cancelled.', 'warn');
      };
    const provider = user.role === 'provider';
    return `<div class="session-banner"><div><span class="kicker">${provider ? 'Provider workspace' : 'Patient workspace'}</span><h1 class="page-title-sm">Good to see you, ${esc(user.name.split(' ')[0])}</h1><p class="breadcrumb">${provider ? 'Keep your facility visible, current and easy for patients to reach.' : 'Your care search, saved facilities and account activity in one place.'}</p></div><button class="btn btn-primary" onclick="openLocator()">${provider ? 'View directory' : 'Find a hospital'}</button></div><div class="metric-row"><div class="metric"><strong>${provider ? '1' : '3'}</strong><span>${provider ? 'Facility profile' : 'Saved facilities'}</span></div><div class="metric"><strong>${provider ? '24/7' : '6'}</strong><span>${provider ? 'Availability status' : 'Sample hospitals nearby'}</span></div><div class="metric"><strong>${provider ? '98%' : '4.7★'}</strong><span>${provider ? 'Profile completeness' : 'Directory rating'}</span></div></div><div class="dashboard-grid"><section class="module-card"><div class="module-heading"><div><span class="kicker">Workspace</span><h3>${provider ? 'Provider tools' : 'Your care shortcuts'}</h3></div><span class="badge badge-info">${provider ? 'Provider' : 'Patient'}</span></div><div class="grid cards-2"><button class="tile" onclick="openLocator()"><div class="t-ic t-blue">🗺️</div><h3>Explore the directory</h3><p>Compare hospitals by care, rating and availability.</p><span class="module-link">Open directory →</span></button><button class="tile" onclick="openEmergency()"><div class="t-ic t-rose">🚨</div><h3>Emergency mode</h3><p>Open the nearest emergency facilities and call options.</p><span class="module-link">Open emergency →</span></button><button class="tile" onclick="openServices()"><div class="t-ic t-green">🩺</div><h3>Browse services</h3><p>Find facilities offering the treatment you need.</p><span class="module-link">Browse services →</span></button><button class="tile" onclick="openContact()"><div class="t-ic t-amber">✉️</div><h3>Contact support</h3><p>Send a question or partnership enquiry.</p><span class="module-link">Send a message →</span></button></div></section><aside class="module-card"><div class="module-heading"><div><span class="kicker">Health signal</span><h3>${provider ? 'Listing health' : 'Care search pulse'}</h3></div><span class="status-dot">● Live</span></div><div class="pulse-card"><div class="pulse-icon">${provider ? '📈' : '📍'}</div><div><b>${provider ? 'Your profile is highly visible' : 'Hospitals are ready to explore'}</b><p>${provider ? 'Your listing is complete and available to patients.' : 'Six sample facilities are available across major Nigerian cities.'}</p></div></div><div class="mini-progress"><div><span>Directory readiness</span><b>${provider ? '98%' : '82%'}</b></div><div class="track"><span style="width:${provider ? '98%' : '82%'}"></span></div></div><div class="module-note">Last updated just now · Offline demo data</div></aside></div><div class="dashboard-grid dashboard-lower"><section class="module-card"><div class="module-heading"><div><span class="kicker">Activity</span><h3>Recent activity</h3></div><button class="text-button" onclick="openNotifPanel()">View notifications</button></div><div class="activity-list"><div class="activity-item"><span class="activity-icon">✓</span><div><b>${provider ? 'Facility profile checked' : 'Directory ready for search'}</b><p>${provider ? 'Your listing information is available to patients.' : 'Search hospitals by location, service or rating.'}</p></div><time>Now</time></div><div class="activity-item"><span class="activity-icon blue">⌁</span><div><b>Offline mode enabled</b><p>All sample records and modules are available without internet.</p></div><time>Today</time></div></div></section><aside class="module-card"><h3>Account status</h3><div class="list-plain"><div class="l-item"><span class="badge badge-verified">Active</span><div><b>Local session verified</b><div class="h-meta">This demo session is stored only in your browser.</div></div></div><div class="l-item"><span class="badge badge-info">${provider ? 'Provider' : 'Patient'}</span><div><b>${provider ? 'Facility listing' : 'Personal profile'}</b><div class="h-meta">Role-based tools are ready to use.</div></div></div></div></aside></div>`;
  }
  function renderPatientAppointments() {
    const appointments = JSON.parse(localStorage.getItem('medilocate-appointments') || '[]');
    const dashboard = $('main-content');
    if (!dashboard || $('patient-appointments')) return;
    const anchor = dashboard.querySelector('.dashboard-lower');
    if (!anchor) return;
    anchor.insertAdjacentHTML('beforebegin', `<section class="patient-appointments module-card" id="patient-appointments"><div class="module-heading"><div><span class="kicker">Care planning</span><h3>My appointments</h3><p class="module-subtitle">Book and manage your next hospital visit from this offline workspace.</p></div><button class="btn btn-primary" onclick="openAppointmentBooking()">+ Book appointment</button></div><div id="appointment-list">${appointmentListMarkup(appointments)}</div></section>`);
  }
  function appointmentListMarkup(appointments) {
    if (!appointments.length) return '<div class="appointment-empty"><span>📅</span><div><b>No appointments booked yet</b><p>Choose a hospital and time to plan your next visit.</p></div><button class="text-button" onclick="openAppointmentBooking()">Book your first appointment →</button></div>';
    return `<div class="appointment-list">${appointments.map((appointment) => `<article class="appointment-item"><div class="appointment-date"><strong>${esc(new Date(`${appointment.date}T00:00:00`).toLocaleDateString('en-US', { day: '2-digit' }))}</strong><span>${esc(new Date(`${appointment.date}T00:00:00`).toLocaleDateString('en-US', { month: 'short' }))}</span></div><div class="appointment-details"><b>${esc(appointment.hospital)}</b><p>${esc(appointment.service)} · ${esc(appointment.time)}</p><small>📍 ${esc(appointment.location)} · ${esc(appointment.reason)}</small></div><span class="badge badge-info">${esc(appointment.status)}</span><button class="btn btn-outline btn-sm" onclick="cancelAppointment('${appointment.id}')">Cancel</button></article>`).join('')}</div>`;
  }
  window.openAppointmentBooking = () => {
    const today = new Date().toISOString().slice(0, 10);
    openModal(`<div class="modal-head"><h3>Book an appointment</h3><button class="close-x" onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-body"><p class="panel-note">Select a facility, service, and preferred time. This offline booking is saved in your browser.</p><form id="appointment-form" onsubmit="saveAppointment(event)"><div class="field"><label for="appointment-hospital">Hospital</label><select id="appointment-hospital" required>${hospitals.map((hospital) => `<option value="${hospital.id}">${esc(hospital.name)} · ${esc(hospital.city)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="appointment-service">Service</label><select id="appointment-service" required>${[...new Set(hospitals.flatMap((hospital) => hospital.services))].sort().map((service) => `<option>${esc(service)}</option>`).join('')}</select></div><div class="field"><label for="appointment-date">Date</label><input id="appointment-date" type="date" min="${today}" required></div><div class="field"><label for="appointment-time">Time</label><select id="appointment-time" required><option>08:00 AM</option><option>09:30 AM</option><option>11:00 AM</option><option>01:30 PM</option><option>03:00 PM</option></select></div><div class="field"><label for="appointment-reason">Visit reason</label><input id="appointment-reason" required placeholder="e.g. Follow-up consultation"></div></div><button class="btn btn-primary btn-block" type="submit">Confirm appointment</button></form></div>`, 'lg');
  };
  window.saveAppointment = (event) => {
    event.preventDefault();
    const hospital = hospitals.find((item) => item.id === Number($('appointment-hospital').value));
    const appointments = JSON.parse(localStorage.getItem('medilocate-appointments') || '[]');
    appointments.push({ id: `apt-${Date.now()}`, hospital: hospital.name, location: `${hospital.city}, ${hospital.state}`, service: $('appointment-service').value, date: $('appointment-date').value, time: $('appointment-time').value, reason: $('appointment-reason').value.trim(), status: 'Confirmed' });
    appointments.sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));
    localStorage.setItem('medilocate-appointments', JSON.stringify(appointments));
    closeModal();
    $('appointment-list').innerHTML = appointmentListMarkup(appointments);
    toast('Appointment booked successfully.');
  };
  window.cancelAppointment = (id) => {
    const appointments = JSON.parse(localStorage.getItem('medilocate-appointments') || '[]').filter((appointment) => appointment.id !== id);
    localStorage.setItem('medilocate-appointments', JSON.stringify(appointments));
    $('appointment-list').innerHTML = appointmentListMarkup(appointments);
    toast('Appointment cancelled.', 'warn');
  };

  function adminMarkup(user) {
    const pending = hospitals.filter((hospital) => !hospital.verified).length;
    const localUsers = JSON.parse(localStorage.getItem('medilocate-users') || '[]');
    return `<div class="admin-hero"><div><span class="kicker">Control centre</span><h1 class="page-title-sm">Admin dashboard</h1><p class="breadcrumb">Manage the directory, review facilities, and keep MediLocate data trustworthy.</p></div><button class="btn btn-white-lg" onclick="openHospitalEditor()">+ Add hospital</button></div><div class="admin-stats"><div class="admin-stat"><span class="admin-stat-icon teal">🏥</span><div><strong>${hospitals.length}</strong><span>Total hospitals</span></div></div><div class="admin-stat"><span class="admin-stat-icon blue">✓</span><div><strong>${hospitals.filter((hospital) => hospital.verified).length}</strong><span>Verified listings</span></div></div><div class="admin-stat"><span class="admin-stat-icon amber">◷</span><div><strong>${pending}</strong><span>Needs review</span></div></div><div class="admin-stat"><span class="admin-stat-icon rose">♙</span><div><strong>${localUsers.length + demoUsers.length}</strong><span>Registered users</span></div></div></div><div class="admin-tabs"><button class="active" data-admin-section="overview" onclick="adminSetSection('overview')">Overview</button><button data-admin-section="hospitals" onclick="adminSetSection('hospitals')">Hospital directory</button><button data-admin-section="users" onclick="adminSetSection('users')">Users</button><button data-admin-section="moderation" onclick="adminSetSection('moderation')">Moderation queue</button></div><section id="admin-overview" class="admin-section"><div class="admin-columns"><div class="admin-panel"><div class="admin-panel-head"><div><span class="kicker">Directory health</span><h2>Hospital records</h2></div><button class="text-button" onclick="adminSetSection('hospitals')">Manage all →</button></div><div class="admin-chart"><div><span>Verified</span><b>${hospitals.filter((hospital) => hospital.verified).length}/${hospitals.length}</b></div><div class="admin-track"><span style="width:${Math.round((hospitals.filter((hospital) => hospital.verified).length / hospitals.length) * 100)}%"></span></div><div class="admin-list-row"><span>Emergency availability</span><b>${hospitals.filter((hospital) => hospital.emergency).length} facilities</b></div><div class="admin-list-row"><span>Open 24 hours</span><b>${hospitals.filter((hospital) => hospital.open24).length} facilities</b></div></div></div><div class="admin-panel"><div class="admin-panel-head"><div><span class="kicker">Attention needed</span><h2>Review queue</h2></div><span class="badge badge-pending">${pending} pending</span></div><div class="admin-review-list">${hospitals.filter((hospital) => !hospital.verified).slice(0, 3).map((hospital) => `<div class="admin-review-item"><span class="review-avatar">${esc(hospital.name.slice(0, 2).toUpperCase())}</span><div><b>${esc(hospital.name)}</b><p>${esc(hospital.city)} · Verification required</p></div><button class="btn btn-outline btn-sm" onclick="adminEditHospital(${hospital.id})">Review</button></div>`).join('') || '<div class="empty"><h4>All records are verified</h4><p>Your directory is up to date.</p></div>'}</div></div></div><div class="admin-panel admin-activity"><div class="admin-panel-head"><div><span class="kicker">System</span><h2>Recent activity</h2></div><span class="status-dot">● Local storage</span></div><div class="activity-list"><div class="activity-item"><span class="activity-icon">✓</span><div><b>Admin workspace loaded</b><p>Directory data is available offline for editing.</p></div><time>Now</time></div><div class="activity-item"><span class="activity-icon blue">⌁</span><div><b>${hospitals.length} hospital records indexed</b><p>Search, edit, verify, or remove records from the directory.</p></div><time>Today</time></div></div></div></section><section id="admin-hospitals" class="admin-section hidden"><div class="admin-panel"><div class="admin-panel-head"><div><span class="kicker">CRUD management</span><h2>Hospital directory</h2></div><button class="btn btn-primary" onclick="openHospitalEditor()">+ Add hospital</button></div><div class="admin-toolbar"><input id="admin-hospital-search" placeholder="Search hospital, city or state" oninput="renderAdminHospitals()"><select id="admin-hospital-filter" onchange="renderAdminHospitals()"><option value="all">All statuses</option><option value="verified">Verified</option><option value="pending">Needs review</option></select></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Hospital</th><th>Location</th><th>Category</th><th>Status</th><th>Actions</th></tr></thead><tbody id="admin-hospital-rows"></tbody></table></div></div></section><section id="admin-users" class="admin-section hidden"><div class="admin-panel"><div class="admin-panel-head"><div><span class="kicker">Access control</span><h2>Registered users</h2></div><span class="badge badge-info">${localUsers.length + demoUsers.length} accounts</span></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>User</th><th>Role</th><th>Source</th><th>Status</th><th>Actions</th></tr></thead><tbody>${[...demoUsers.map((entry) => ({ ...entry, source: 'Demo account' })), ...localUsers.map((entry) => ({ ...entry, source: 'Local registration' }))].map((entry) => `<tr><td><b>${esc(entry.name)}</b><small>${esc(entry.email)}</small></td><td><span class="role-badge rb-${esc(entry.role)}">${esc(entry.role)}</span></td><td>${esc(entry.source)}</td><td><span class="badge badge-verified">Active</span></td><td><button class="btn btn-outline btn-sm" onclick="toast('User details are read-only in this offline build.','warn')">View</button></td></tr>`).join('')}</tbody></table></div></div></section><section id="admin-moderation" class="admin-section hidden"><div class="admin-panel"><div class="admin-panel-head"><div><span class="kicker">Trust and safety</span><h2>Moderation queue</h2></div><span class="badge badge-pending">${pending} to review</span></div><div class="moderation-grid">${hospitals.filter((hospital) => !hospital.verified).map((hospital) => `<article class="moderation-card"><span class="review-avatar">${esc(hospital.name.slice(0, 2).toUpperCase())}</span><h3>${esc(hospital.name)}</h3><p>${esc(hospital.category)} · ${esc(hospital.city)}, ${esc(hospital.state)}</p><div><button class="btn btn-primary btn-sm" onclick="adminVerifyHospital(${hospital.id})">Approve</button><button class="btn btn-danger btn-sm" onclick="adminDeleteHospital(${hospital.id})">Remove</button></div></article>`).join('') || '<div class="empty"><h4>Nothing waiting for review</h4></div>'}</div></div></section>`;
  }
  function persistHospitals() { localStorage.setItem('medilocate-hospitals', JSON.stringify(hospitals)); }
  window.adminSetSection = (section) => { document.querySelectorAll('.admin-section').forEach((panel) => panel.classList.toggle('hidden', panel.id !== `admin-${section}`)); document.querySelectorAll('[data-admin-section]').forEach((button) => button.classList.toggle('active', button.dataset.adminSection === section)); if (section === 'hospitals') renderAdminHospitals(); };
  window.renderAdminHospitals = () => { const query = ($('admin-hospital-search')?.value || '').toLowerCase(); const filter = $('admin-hospital-filter')?.value || 'all'; const rows = hospitals.filter((hospital) => (!query || `${hospital.name} ${hospital.city} ${hospital.state}`.toLowerCase().includes(query)) && (filter === 'all' || filter === 'verified' && hospital.verified || filter === 'pending' && !hospital.verified)); $('admin-hospital-rows').innerHTML = rows.map((hospital) => `<tr><td><b>${esc(hospital.name)}</b><small>${esc(hospital.phone)}</small></td><td>${esc(hospital.city)}, ${esc(hospital.state)}</td><td>${esc(hospital.category)}</td><td><span class="badge ${hospital.verified ? 'badge-verified' : 'badge-pending'}">${hospital.verified ? 'Verified' : 'Needs review'}</span></td><td><div class="t-row-actions"><button class="btn btn-outline btn-sm" onclick="adminEditHospital(${hospital.id})">Edit</button><button class="btn btn-danger btn-sm" onclick="adminDeleteHospital(${hospital.id})">Delete</button></div></td></tr>`).join('') || '<tr><td colspan="5"><div class="empty"><h4>No matching records</h4></div></td></tr>'; };
  window.openHospitalEditor = (id = '') => { const hospital = hospitals.find((item) => item.id === id); const record = hospital || { name: '', city: '', state: '', category: 'Private Hospital', rating: 0, reviews: 0, emergency: false, open24: false, verified: false, phone: '', services: ['General Care'], lat: 50, lng: 50 }; openModal(`<div class="modal-head"><h3>${hospital ? 'Edit hospital record' : 'Add hospital record'}</h3><button class="close-x" onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-body"><form id="hospital-form" onsubmit="saveAdminHospital(event,${hospital ? id : 'null'})"><div class="form-grid"><div class="field"><label>Hospital name</label><input id="admin-name" required value="${esc(record.name)}"></div><div class="field"><label>Phone</label><input id="admin-phone" required value="${esc(record.phone)}"></div><div class="field"><label>City</label><input id="admin-city" required value="${esc(record.city)}"></div><div class="field"><label>State</label><input id="admin-state" required value="${esc(record.state)}"></div><div class="field"><label>Category</label><select id="admin-category"><option ${record.category === 'Teaching Hospital' ? 'selected' : ''}>Teaching Hospital</option><option ${record.category === 'Private Hospital' ? 'selected' : ''}>Private Hospital</option><option ${record.category === 'Medical Centre' ? 'selected' : ''}>Medical Centre</option></select></div><div class="field"><label>Services</label><input id="admin-services" required value="${esc(record.services.join(', '))}"></div></div><label class="check-row"><input id="admin-emergency" type="checkbox" ${record.emergency ? 'checked' : ''}> Emergency available</label><label class="check-row" style="margin-top:10px"><input id="admin-open24" type="checkbox" ${record.open24 ? 'checked' : ''}> Open 24 hours</label><label class="check-row" style="margin-top:10px"><input id="admin-verified" type="checkbox" ${record.verified ? 'checked' : ''}> Mark as verified</label><button class="btn btn-primary btn-block" style="margin-top:20px" type="submit">Save hospital record</button></form></div>`,'lg'); };
  window.adminEditHospital = (id) => openHospitalEditor(id);
  window.saveAdminHospital = (event, id) => { event.preventDefault(); const existing = hospitals.find((hospital) => hospital.id === id); const record = { id: id || Math.max(...hospitals.map((hospital) => hospital.id), 0) + 1, name: $('admin-name').value.trim(), phone: $('admin-phone').value.trim(), city: $('admin-city').value.trim(), state: $('admin-state').value.trim(), category: $('admin-category').value, services: $('admin-services').value.split(',').map((item) => item.trim()).filter(Boolean), emergency: $('admin-emergency').checked, open24: $('admin-open24').checked, verified: $('admin-verified').checked, rating: existing?.rating || 0, reviews: existing?.reviews || 0, lat: existing?.lat || 50, lng: existing?.lng || 50 }; if (existing) Object.assign(existing, record); else hospitals.push(record); persistHospitals(); closeModal(); toast(`${record.name} ${existing ? 'updated' : 'added'} successfully.`); const session = JSON.parse(sessionStorage.getItem('medilocate-session') || 'null'); if (session?.role === 'admin') { $('main-content').innerHTML = adminMarkup(session); adminSetSection('hospitals'); } };
  window.adminDeleteHospital = (id) => { const index = hospitals.findIndex((hospital) => hospital.id === id); if (index < 0) return; const name = hospitals[index].name; hospitals.splice(index, 1); persistHospitals(); toast(`${name} was removed from the directory.`,'warn'); const session = JSON.parse(sessionStorage.getItem('medilocate-session') || 'null'); if (session?.role === 'admin') { $('main-content').innerHTML = adminMarkup(session); adminSetSection('hospitals'); } };
  window.adminVerifyHospital = (id) => { const hospital = hospitals.find((item) => item.id === id); if (!hospital) return; hospital.verified = true; persistHospitals(); toast(`${hospital.name} is now verified.`); const session = JSON.parse(sessionStorage.getItem('medilocate-session') || 'null'); if (session?.role === 'admin') $('main-content').innerHTML = adminMarkup(session); };
  window.logout = () => { sessionStorage.removeItem('medilocate-session'); $('app').classList.add('hidden'); goLanding(); toast('You have been signed out.'); };
  window.openNotifPanel = () => openModal('<div class="modal-head"><h3>Notifications</h3><button class="close-x" onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-body"><div class="notif-unread"><b>Welcome to MediLocate</b><p class="h-meta">Your local workspace is ready. Start by searching for a hospital or service.</p></div></div>');

  function populateFilters() {
    const categories = [...new Set(hospitals.map((hospital) => hospital.category))];
    const services = [...new Set(hospitals.flatMap((hospital) => hospital.services))].sort();
    $('f-cat').innerHTML = '<option value="">All categories</option>' + categories.map((item) => `<option>${esc(item)}</option>`).join('');
    $('f-service').innerHTML = '<option value="">All services</option>' + services.map((item) => `<option>${esc(item)}</option>`).join('');
    $('radius-pills').innerHTML = [5, 10, 25, 50, 100].map((radius) => `<button class="${radius === state.radius ? 'active' : ''}" onclick="setRadius(${radius})">${radius} km</button>`).join('');
  }
  window.setRadius = (radius) => { state.radius = radius; populateFilters(); applyFilters(); };
  window.resetFilters = () => { ['f-name', 'f-location'].forEach((id) => { $(id).value = ''; }); ['f-cat', 'f-service'].forEach((id) => { $(id).value = ''; }); $('f-rating').value = '0'; ['f-emergency', 'f-open24', 'f-opennow', 'f-verified'].forEach((id) => { $(id).checked = false; }); $('f-sort').value = 'nearest'; state.radius = 25; populateFilters(); applyFilters(); };
  window.applyFilters = () => {
    const name = ($('f-name')?.value || '').toLowerCase();
    const location = ($('f-location')?.value || '').toLowerCase();
    const category = $('f-cat')?.value || '';
    const service = $('f-service')?.value || '';
    const minimumRating = Number($('f-rating')?.value || 0);
    state.results = hospitals.filter((hospital) => (!name || hospital.name.toLowerCase().includes(name)) && (!location || `${hospital.city} ${hospital.state}`.toLowerCase().includes(location)) && (!category || hospital.category === category) && (!service || hospital.services.includes(service)) && hospital.rating >= minimumRating && (!$('f-emergency')?.checked || hospital.emergency) && (!$('f-open24')?.checked || hospital.open24) && (!$('f-opennow')?.checked || hospital.open24) && (!$('f-verified')?.checked || hospital.verified));
    const sort = $('f-sort')?.value || 'nearest';
    state.results.sort((a, b) => sort === 'rating' ? b.rating - a.rating : sort === 'reviews' ? b.reviews - a.reviews : a.id - b.id);
    $('loc-count').textContent = `${state.results.length} hospital${state.results.length === 1 ? '' : 's'} found`;
    $('loc-list').innerHTML = state.results.length ? state.results.map((hospital) => hospitalCard(hospital)).join('') : '<div class="empty"><div class="e-ic">🔎</div><h4>No hospitals match these filters</h4><p>Try widening your search or resetting the filters.</p></div>';
    if (!$('loc-map-wrap').classList.contains('hidden')) renderMap('map-canvas', state.results);
  };
  window.toggleViewMode = (mode) => { $('seg-list').classList.toggle('active', mode === 'list'); $('seg-map').classList.toggle('active', mode === 'map'); $('loc-list').classList.toggle('hidden', mode === 'map'); $('loc-map-wrap').classList.toggle('hidden', mode !== 'map'); if (mode === 'map') renderMap('map-canvas', state.results); };
  function renderMap(containerId, items) { const root = $(containerId); if (!root) return; root.querySelectorAll('.map-pin, .map-empty').forEach((node) => node.remove()); items.forEach((hospital) => { const pin = document.createElement('button'); pin.className = `map-pin ${hospital.emergency ? 'em' : ''}`; pin.style.left = `${hospital.lng}%`; pin.style.top = `${hospital.lat}%`; pin.title = hospital.name; pin.innerHTML = `<span class="pin"><span>🏥</span></span><span class="h-label">${esc(hospital.name)}</span>`; pin.onclick = () => showHospital(hospital.id); root.appendChild(pin); }); }
  window.setMapType = (type) => { state.mapType = type; $('mtype-road').classList.toggle('active', type === 'road'); $('mtype-sat').classList.toggle('active', type === 'sat'); $('map-canvas').style.filter = type === 'sat' ? 'saturate(.7) contrast(1.08)' : ''; };
  window.mapZoom = (delta) => { state.mapZoom = Math.max(.7, Math.min(1.5, state.mapZoom + delta * .1)); $('map-canvas').style.backgroundSize = `${44 * state.mapZoom}px ${44 * state.mapZoom}px`; };
  window.heroSearch = (query = '') => { openLocator(); $('f-name').value = $('hero-h-name').value || (query && !query.includes(' ') ? query : ''); $('f-location').value = $('hero-location').value; if (query && !$('f-name').value) $('f-service').value = [...$('f-service').options].find((option) => option.text.toLowerCase() === query.toLowerCase())?.value || ''; applyFilters(); };
  window.useMyLocation = () => { if (!navigator.geolocation) { toast('Location is unavailable in this browser. Search by city instead.', 'warn'); return; } navigator.geolocation.getCurrentPosition((position) => { state.userLocation = position.coords; if ($('f-location')) $('f-location').value = 'My current location'; toast('Location received. Sample records are shown in offline mode.'); if (state.view !== 'locator') openLocator(); }, () => toast('Location permission was not granted. You can search by city instead.', 'warn')); };

  function renderEmergency() { const emergencyHospitals = hospitals.filter((hospital) => hospital.emergency); $('emg-list').innerHTML = emergencyHospitals.map((hospital) => `<div class="l-item"><div style="flex:1"><b>${esc(hospital.name)}</b><div class="h-meta">📍 ${esc(hospital.city)} · ${hospital.rating} ★ · Open 24 hours</div></div><a class="btn btn-danger btn-sm" href="tel:${hospital.phone.replace(/\s/g, '')}">Call</a></div>`).join(''); renderMap('emg-map', emergencyHospitals); }
  window.runEmergencySearch = () => { renderEmergency(); toast('Emergency facilities are shown from the local sample directory.'); };
  window.renderServices = () => { const query = ($('svc-search')?.value || '').toLowerCase(); const services = [...new Set(hospitals.flatMap((hospital) => hospital.services))].filter((service) => !query || service.toLowerCase().includes(query)); $('svc-grid').innerHTML = services.map((service) => `<button class="tile" style="text-align:left" onclick="serviceSearch('${service.replace(/'/g, "\\'")}')"><div class="t-ic t-blue">🩺</div><h3>${esc(service)}</h3><p>${hospitals.filter((hospital) => hospital.services.includes(service)).length} hospitals available</p></button>`).join(''); if (!$('svc-results').innerHTML) $('svc-results').innerHTML = '<div class="panel-body"><p class="panel-note">Choose a service to see matching hospitals.</p></div>'; };
  window.serviceSearch = (service = '') => { if (service) $('svc-search').value = service; const query = ($('svc-search').value || '').toLowerCase(); const matches = hospitals.filter((hospital) => !query || hospital.services.some((item) => item.toLowerCase().includes(query))); $('svc-results').innerHTML = `<div class="panel-head"><h3>${query ? `Hospitals offering “${esc($('svc-search').value)}”` : 'All service providers'}</h3></div><div class="panel-body loc-results">${matches.length ? matches.map((hospital) => hospitalCard(hospital, true)).join('') : '<div class="empty"><h4>No matching hospitals</h4></div>'}</div>`; };
  window.submitContact = (event) => { event.preventDefault(); event.target.reset(); toast('Thanks. Your message has been queued in this demo.'); };
  window.openPlans = () => openModal('<div class="modal-head"><h3>Subscription Plans</h3><button class="close-x" onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-body"><div class="plans-grid"><div class="plan"><h3>Free</h3><div class="price">₦0 <small>/ month</small></div><p>Basic directory listing for patients.</p></div><div class="plan popular"><h3>Standard</h3><div class="price">₦25k <small>/ month</small></div><p>Enhanced visibility and patient enquiries.</p></div><div class="plan"><h3>Premium</h3><div class="price">₦60k <small>/ month</small></div><p>Featured placement and analytics.</p></div></div></div>');
  window.showVerificationInfo = () => openModal('<div class="modal-head"><h3>Hospital verification</h3><button class="close-x" onclick="closeModal()" aria-label="Close">×</button></div><div class="modal-body"><p>Verified listings are reviewed against facility registration, contact details and service information. Register an account to submit your facility for review.</p></div>');

  function init() { $('fy').textContent = new Date().getFullYear(); const serviceList = [...new Set(hospitals.flatMap((hospital) => hospital.services))]; $('hero-stats').innerHTML = `<div class="stat-card"><div class="num">${hospitals.length}</div><div class="lbl">Sample hospitals</div></div><div class="stat-card"><div class="num">${serviceList.length}</div><div class="lbl">Medical services</div></div><div class="stat-card"><div class="num">${hospitals.filter((hospital) => hospital.emergency).length}</div><div class="lbl">Emergency facilities</div></div>`; $('landing-hospitals').innerHTML = hospitals.slice(0, 4).map((hospital) => hospitalCard(hospital, true)).join(''); $('landing-featured').innerHTML = hospitals.slice(0, 3).map((hospital) => hospitalCard(hospital, true)).join(''); $('landing-categories').innerHTML = [...new Set(hospitals.map((hospital) => hospital.category))].map((category) => `<button class="tile" onclick="openLocator();$('f-cat').value='${category.replace(/'/g, "\\'")}';applyFilters()"><div class="t-ic t-blue">🏥</div><h3>${esc(category)}</h3><p>Browse verified facilities in this category.</p></button>`).join(''); $('landing-services').innerHTML = serviceList.slice(0, 4).map((service) => `<button class="tile" onclick="openServices();serviceSearch('${service.replace(/'/g, "\\'")}')"><div class="t-ic t-green">🩺</div><h3>${esc(service)}</h3><p>Find hospitals providing ${esc(service.toLowerCase())}.</p></button>`).join(''); const existingSession = JSON.parse(sessionStorage.getItem('medilocate-session') || 'null'); if (existingSession) startSession(existingSession); }
  document.addEventListener('DOMContentLoaded', init);
})();
